pub(crate) fn lookup(name: &str) -> Option<&'static DvarSpec> {
    let lower = name.to_ascii_lowercase();
    DVARS
        .binary_search_by(|d| d.name.to_ascii_lowercase().as_str().cmp(lower.as_str()))
        .ok()
        .map(|i| &DVARS[i])
}

pub(crate) fn lookup_hash(hash: u32) -> Option<&'static DvarSpec> {
    DVARS.iter().find(|d| super::dvar_hash(d.name) == hash)
}
